// src/utils/generatePdf.js
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { assessmentAspects, skorLabel } from "../data/assessmentAspects";

// Logo New Hemangini Hotel, disematkan langsung sebagai base64 supaya PDF
// tidak bergantung pada file gambar eksternal.
const LOGO_BASE64 = "data:image/png;base64,";

export function generateHasilPenilaianPdf(data, konversi) {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.getWidth();
  doc.setFont("times", "normal");
  let y = 15;

  // ===== LOGO (pojok kiri atas) =====
  const logoWidth = 22;
  const logoHeight = 22 * (235 / 300);
  try {
    doc.addImage(LOGO_BASE64, "PNG", 14, y, logoWidth, logoHeight);
  } catch (e) {
    // Kalau logo gagal dimuat, lanjutkan tanpa logo (tidak menggagalkan PDF)
  }

  // ===== HEADER =====
  doc.setFontSize(13);
  doc.setFont("times", "bold");
  doc.text("HASIL PENILAIAN JOBS PERFORMANCE MAKING BED", pageWidth / 2 + 10, y + 6, {
    align: "center",
  });
  doc.setFontSize(9);
  doc.setFont("times", "normal");
  doc.text(
    'Berdasarkan SOP Housekeeping "Making The Bed", New Hemangini Hotel',
    pageWidth / 2 + 10,
    y + 12,
    { align: "center" }
  );

  y += logoHeight + 6;
  doc.setLineWidth(0.4);
  doc.line(14, y, pageWidth - 14, y);
  y += 8;

  // ===== IDENTITAS =====
  doc.setFontSize(10);
  const identitas = [
    ["Nama Peserta Magang", data.peserta.nama],
    ["Instansi", data.peserta.instansi],
    ["Nama Penilai", data.peserta.penilai],
    ["Tanggal Penilaian", data.peserta.tanggal],
  ];
  identitas.forEach(([label, value]) => {
    doc.setFont("times", "bold");
    doc.text(label, 14, y);
    doc.setFont("times", "normal");
    doc.text(": " + value, 65, y);
    y += 6;
  });
  y += 4;

  // ===== RINGKASAN NILAI =====
  doc.setFillColor(230, 244, 254);
  doc.rect(14, y, pageWidth - 28, 24, "F");

  doc.setFontSize(22);
  doc.setFont("times", "bold");
  doc.setTextColor(12, 74, 110);
  doc.text(String(data.hasil.persentase) + " / 100", 20, y + 15);

  doc.setFontSize(10);
  doc.setFont("times", "bold");
  doc.setTextColor(0, 0, 0);
  doc.text("Kategori:", 75, y + 9);
  doc.text("Status Kompetensi:", 75, y + 16);
  doc.setFont("times", "normal");
  doc.text(konversi.kategori, 105, y + 9);
  doc.text(data.hasil.status, 118, y + 16);
  y += 32;

  doc.setFontSize(9);
  doc.setFont("times", "italic");
  const keteranganLines = doc.splitTextToSize(konversi.keterangan, pageWidth - 28);
  doc.text(keteranganLines, 14, y);
  y += keteranganLines.length * 4 + 6;

  // ===== TABEL SKOR PER ASPEK =====
  const kategoriList = ["Hard Skill", "Soft Skill", "Technical Skill"];
  const rows = [];
  kategoriList.forEach((kategori) => {
    assessmentAspects
      .filter((a) => a.kategori === kategori)
      .forEach((aspek) => {
        const j = data.jawaban[aspek.id];
        rows.push([
          String(aspek.id).padStart(2, "0"),
          kategori,
          aspek.judul,
          j ? j.skor : "-",
          j ? skorLabel[j.skor] : "-",
        ]);
      });
  });

  autoTable(doc, {
    startY: y,
    head: [["No", "Kategori", "Aspek", "Skor", "Label"]],
    body: rows,
    styles: { font: "times", fontSize: 9, cellPadding: 2.5, fontStyle: "normal" },
    headStyles: { font: "times", fontStyle: "bold", fillColor: [12, 74, 110], fontSize: 9 },
    columnStyles: {
      0: { cellWidth: 10 },
      1: { cellWidth: 28 },
      2: { cellWidth: "auto" },
      3: { cellWidth: 15, halign: "center" },
      4: { cellWidth: 25 },
    },
  });

  y = doc.lastAutoTable.finalY + 8;

  if (y > 240) {
    doc.addPage();
    y = 20;
  }

  // ===== CATATAN UMUM =====
  if (data.catatan_umum) {
    doc.setFontSize(10);
    doc.setFont("times", "bold");
    doc.text("Catatan & Rekomendasi Tindak Lanjut:", 14, y);
    y += 6;
    doc.setFont("times", "normal");
    doc.setFontSize(9);
    const catatanLines = doc.splitTextToSize(data.catatan_umum, pageWidth - 28);
    doc.text(catatanLines, 14, y);
    y += catatanLines.length * 4 + 10;
  }

  // ===== TANDA TANGAN =====
  if (y > 240) {
    doc.addPage();
    y = 20;
  }
  y += 10;

  const today = new Date().toLocaleDateString("id-ID", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });

   doc.setFontSize(9);
  doc.setFont("times", "normal");
  doc.text("Bandung, " + today, pageWidth - 70, y);
  doc.text("Bandung, " + today, 14, y);
  y += 6;
  doc.text("Peserta Magang,", 14, y);
  doc.text("Penilai,", pageWidth - 70, y);
  y += 25;
  doc.text("" + data.peserta.nama + "", 14, y);
  doc.text("Letty Latifah SE, MM Par", pageWidth - 70, y);

  const namaFile =
    "Hasil_Penilaian_" +
    data.peserta.nama.replace(/\s+/g, "_") +
    "_" +
    data.peserta.tanggal.replace(/\//g, "-") +
    ".pdf";
  doc.save(namaFile);
}
